// @ts-nocheck
/* eslint-disable */
/** Prospect documents engine. GENERATED by tools/sync-prospect-docs.mjs from the generated prospect form (prospect-form.{html,engine.ts,scss}) — do not edit; change the generator and run `npm run prospect-docs:sync`
 *
 * The documents part of the page script of contracts_master_data.xhtml, same code as the form's engine: upload (POST /board/prospect/attachments), download (through
 * /docproxy), delete (confirm, then the host's `rc_deleteProspectDoc`). The list itself is drawn by the template; `rc_reloadProspectDocs` / `rc_deleteProspectDoc`
 * are the p:remoteCommand functions the host defines (as PrimeFaces did for the form).
 */

export interface ProspectDocsEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** SweetAlert (the library of the Java page) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** the id of the prospect (the script reads it as window._contractId) */
  contractId: string;
  /** the browser's own requests (/board/prospect/attachments · /docproxy) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
}

export function startProspectDocs(env: ProspectDocsEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

  /* the global the script reads: the id of the record */
  window._contractId = env.contractId;

  /* ===== เอกสารประกอบ (Tab 3) — อัปโหลดจริงผ่าน API (/attachments) + insert DB; รายการ render จาก server (#{contractView.prospectDocs}) ===== */
                    /* ★ 10/08: เปลี่ยนจากส่งไฟล์ผ่าน p:remoteCommand (JSF postback) → fetch ไป servlet โดยตรง
                       เหตุผล: remoteCommand ส่งแบบ application/x-www-form-urlencoded ซึ่งติดเพดาน Tomcat
                       maxPostSize = 2MB (ค่า default, connector ใน server.xml ไม่ได้ตั้งค่านี้ไว้)
                       ไฟล์ผ่าน base64 บวม ~1.37 เท่า + ถูก url-encode ต่ออีก ⇒ ไฟล์เกิน ~1.2MB จะโดน Tomcat ตัดพารามิเตอร์ทิ้ง
                       bean เลยไม่เห็น docB64 → ไม่มีอะไรเกิดขึ้น ไม่มี error (อาการ "กดแล้วไม่ขึ้น" ของ pdf/word/excel
                       ซึ่งมักไฟล์ใหญ่กว่า jpg ที่เคยลอง) — ส่วน fetch เป็น body JSON ธรรมดา ไม่ถูก parse เป็นพารามิเตอร์
                       จึงไม่ติดเพดานนี้ (เส้นเดียวกับที่หน้า lead_detail ใช้อยู่แล้ว = /board/prospect/attachments) */
                    /* ★ 26/08 เพดานขนาดไฟล์ — เดิมตั้งไว้ 20 MB ซึ่ง "เป็นไปไม่ได้" ตั้งแต่แรก
                       backend ตั้ง Jackson StreamReadConstraints.getMaxStringLength() = 20,000,000 ตัวอักษร
                       ต่อ 1 ค่า string ใน JSON และไฟล์ถูกส่งเป็น base64 ใน field fileContentBase64
                       base64 ยาว = 4 * ceil(bytes/3) ⇒ ไฟล์ใหญ่สุดที่ backend รับได้ = 15,000,000 bytes ≈ 14.31 MiB
                       (ยืนยันจากของจริง: ไฟล์ 14.34 MiB -> 20,051,112 ตัวอักษร -> backend ตอบ 400 "Malformed request body")
                       ⇒ เช็คด้วยความยาว base64 จริง ไม่ใช่เดาเป็น MB จะได้ตรงกับสิ่งที่ backend วัด
                       ถ้าวันหลัง backend ขยาย limit ให้แก้ CT_MD_API_MAX_B64_CHARS ตัวเดียว */
                    var CT_MD_API_MAX_B64_CHARS = 20000000;
                    var CT_MD_MAX_FILE_BYTES = Math.floor(CT_MD_API_MAX_B64_CHARS / 4) * 3;
                    var CT_MD_MAX_FILE_MB = (CT_MD_MAX_FILE_BYTES / 1024 / 1024).toFixed(1);
                    /* ★ 13/08: ข้อความของ flow อัปโหลด รวมไว้ที่เดียว (เดิมภาษาไทย hardcode กระจายในฟังก์ชัน) */
                    var CT_MD_MSG = {
                        upload:    env.t("label.cmd.upload_docs"),
                        uploading: env.t("label.cmd.uploading"),
                        done:      env.t("label.cmd.upload_done"),
                        failed:    env.t("label.cmd.upload_fail_count"),
                        fileUnit:  env.t("label.cmd.file_unit"),
                        tooLarge:  env.t("label.cmd.file_too_large"),
                        uploadFail:env.t("label.ld2.upload_failed"),
                        readFail:  env.t("label.cmd.file_read_failed")
                    };
                    /* ★ 28/09/2026 ตรวจนามสกุลไฟล์ "ก่อน" ยิง API (ไฟล์กลาง resources/js/attach_file_types.js — ชุดเดียวกับ lead_detail/contracts) */
                    var CT_MD_ATTACH_MSG = {
                        notAllowed:    env.t("label.rv.file_type_not_allowed"),
                        allowed:       env.t("label.rv.file_type_allowed")
                    };
                    var ctMdUploading = false;
    
                    /* เปิดหน้าต่างเลือกไฟล์ — กันกดซ้ำระหว่างที่ยังอัปไม่เสร็จ
                       (เดิมปุ่มกดได้ตลอด กดซ้ำ = เกิด chain อัปโหลดซ้อนกัน ไฟล์ถูกอัปซ้ำ) */
                    function ctMdPickFiles() {
                        if (ctMdUploading) { return; }
                        var el = document.getElementById('ctMdFileInput');
                        if (el) { el.click(); }
                    }
                    /* ปุ่มอัปโหลดระหว่างทำงาน: ไอคอนเป็นสปินเนอร์ + ข้อความ "กำลังอัปโหลด" + กดไม่ได้ */
                    function ctMdSetBusy(busy) {
                        ctMdUploading = busy;
                        var btn = document.getElementById('ctMdUploadBtn');
                        if (!btn) { return; }
                        btn.disabled = busy;
                        btn.style.opacity = busy ? '.6' : '';
                        btn.style.cursor = busy ? 'not-allowed' : 'pointer';
                        var ic = btn.querySelector('i');
                        if (ic) { ic.className = busy ? 'pi pi-spinner pi-spin' : 'pi pi-upload'; }
                        var lb = document.getElementById('ctMdUploadBtnText');
                        if (lb) { lb.textContent = busy ? CT_MD_MSG.uploading : CT_MD_MSG.upload; }
                    }
                    /* แถวสถานะเหนือรายการเอกสาร บอกว่ากำลังอัปไฟล์ไหน ไฟล์ที่เท่าไรจากทั้งหมด
                       ★ สร้างด้วย createElement ไม่ใช่ innerHTML ที่มีแท็ก — script block หน้านี้ไม่ได้อยู่ใน CDATA
                         เครื่องหมายน้อยกว่าในสตริงจะถูก XML parser กลืนไปเป็น element จริง (พังง่ายถ้าแท็กไม่ครบคู่) */
                    function ctMdShowProgress(text) {
                        var el = document.getElementById('ctMdUploadProgress');
                        if (!el) {
                            var panel = document.getElementById('form:ctMdDocPanel');
                            if (!panel) { return; }
                            el = document.createElement('div');
                            el.id = 'ctMdUploadProgress';
                            el.style.cssText = 'display:flex;align-items:center;gap:10px;border:1px solid #E5E7EB;'
                                    + 'border-radius:8px;padding:8px 12px;background:#F9FAFB;color:#35236A;'
                                    + 'font-size:calc(14px + var(--fs-adj,0px));';
                            var ic = document.createElement('i');
                            ic.className = 'pi pi-spinner pi-spin';
                            ic.style.flexShrink = '0';
                            var tx = document.createElement('span');
                            tx.id = 'ctMdUploadProgressText';
                            tx.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
                            el.appendChild(ic);
                            el.appendChild(tx);
                            panel.insertBefore(el, panel.firstChild);
                        }
                        var txt = document.getElementById('ctMdUploadProgressText');
                        if (txt) { txt.textContent = text; }
                    }
                    function ctMdClearProgress() {
                        var el = document.getElementById('ctMdUploadProgress');
                        if (el && el.parentNode) { el.parentNode.removeChild(el); }
                    }
    
                    /* ★ 13/08: เดิมระหว่างอัปโหลด "ไม่มีอะไรขยับบนจอเลย" — ปุ่มเหมือนเดิม ไม่มีสปินเนอร์
                       ไม่มี toast และรายการเอกสารก็เพิ่งวาดใหม่ตอนไฟล์สุดท้ายเสร็จ (rc_reloadProspectDocs
                       ถูกเรียกหลังจบ loop) ⇒ ไฟล์ใหญ่/หลายไฟล์ = จอนิ่งยาว ผู้ใช้ไม่รู้ว่าระบบทำงานอยู่หรือค้าง
                       แจ้งผลเฉพาะตอน error อย่างเดียวด้วย สำเร็จแล้วเงียบสนิท
                       ตอนนี้: ปุ่ม busy + แถบ "กำลังอัปโหลด i/n — ชื่อไฟล์" + สรุปผลตอนจบทุกกรณี */
                    function ctMdOnFilePicked(input) {
                        if (!input || !input.files || !input.files.length) { return; }
                        var pid = window._contractId;
                        if (!pid) { env.swal({ title: CT_MD_MSG.uploadFail, text: env.t("label.ld2.prospect_id_not_found_msg"), icon: 'error' }); input.value = ''; return; }
                        var files = Array.prototype.slice.call(input.files);
                        /* มีไฟล์ไหนนามสกุลไม่ตรง → alert แล้วไม่อัปทั้งชุด (ยังไม่ยิง API เลย) ให้เลือกใหม่ */
                        if (!TsAttachTypes.check(files, input.getAttribute('accept'), CT_MD_ATTACH_MSG)) { input.value = ''; return; }
                        var total = files.length;
                        var okCount = 0;
                        var failCount = 0;
                        /* ★ 26/08: เก็บเหตุผลรายไฟล์ไว้ก่อน แล้วสรุปเป็น popup ทีเดียวตอนจบ
                           เดิมแจ้งด้วย ld2Notify = แถบเล็กมุมล่างจอที่จางหายเองใน 2.2 วินาที
                           user บอกว่าอัปไม่ได้ต้องเด้ง popup — ของเดิมกดอัปไฟล์ใหญ่แล้วแถบวูบหาย
                           ผู้ใช้ไม่ทันเห็น เข้าใจว่าระบบเงียบ ๆ ไม่ทำอะไร */
                        var errs = [];
                        ctMdSetBusy(true);
                        (function next(i) {
                            if (i >= total) {
                                input.value = '';
                                ctMdClearProgress();
                                ctMdSetBusy(false);
                                if (window.rc_reloadProspectDocs) { rc_reloadProspectDocs(); }   /* วาดรายการใหม่จาก server */
                                /* สรุปผลเสมอ 3 กรณี: สำเร็จล้วน / พังบางส่วน / พังหมด
                                   ที่มี fail ต้องกดรับทราบเอง (ไม่ตั้ง timer) จะได้อ่านเหตุผลทัน */
                                if (failCount === 0) {
                                    env.swal({ title: CT_MD_MSG.done + ' ' + okCount + ' ' + CT_MD_MSG.fileUnit, icon: 'success', timer: 2000, buttons: false });
                                } else if (okCount === 0) {
                                    env.swal({ title: CT_MD_MSG.uploadFail, text: errs.join('\n'), icon: 'error' });
                                } else {
                                    env.swal({ title: CT_MD_MSG.done + ' ' + okCount + ' ' + CT_MD_MSG.fileUnit
                                                  + ' · ' + CT_MD_MSG.failed + ' ' + failCount + ' ' + CT_MD_MSG.fileUnit,
                                           text: errs.join('\n'), icon: 'warning' });
                                }
                                return;
                            }
                            var f = files[i];
                            ctMdShowProgress(CT_MD_MSG.uploading + ' ' + (i + 1) + '/' + total + ' — ' + f.name);
                            if (f.size > CT_MD_MAX_FILE_BYTES) {
                                errs.push(f.name + ' — ' + CT_MD_MSG.tooLarge + ' ' + CT_MD_MAX_FILE_MB + ' MB');
                                failCount++;
                                next(i + 1);
                                return;
                            }
                            var reader = new FileReader();
                            reader.onload = function (e) {
                                env.fetch('/board/prospect/attachments', {
                                    method: 'POST',
                                    headers: {'Content-Type': 'application/json'},
                                    credentials: 'same-origin',
                                    body: JSON.stringify({prospectId: pid, fileContentBase64: e.target.result,
                                                          fileName: f.name, description: f.name})
                                })
                                        .then(function (r) { return r.json().catch(function () { return {}; }); })
                                        .then(function (res) {
                                            if (res && (res.ok === true || res.status === 200 || res.status === 201)) {
                                                okCount++;
                                            } else {
                                                failCount++;
                                                errs.push(f.name + ' — ' + (res && res.message ? res.message : CT_MD_MSG.uploadFail));
                                            }
                                        })
                                        ['catch'](function (err) {
                                            console.error(err);
                                            failCount++;
                                            errs.push(f.name + ' — ' + CT_MD_MSG.uploadFail);
                                        })
                                        .then(function () { next(i + 1); });
                            };
                            reader.onerror = function () {
                                failCount++;
                                errs.push(f.name + ' — ' + CT_MD_MSG.readFail);
                                next(i + 1);
                            };
                            reader.readAsDataURL(f);
                        })(0);
                    }
                    /* ★ 21/08: ของเดิมลบเอกสารทันทีไม่มี confirm เลยสักจุด (data-loss risk) — ต่างจาก
                       contracts.xhtml ที่มี window.confirm() ของเบราว์เซอร์อยู่ (คนละสไตล์กับ swal ที่ใช้ทั่วระบบ) —
                       ทำให้เหมือนกันทั้ง 2 หน้าด้วย swal แบบ confirm (buttons สอง ปุ่ม) ข้อความเดียวกับที่
                       contracts.xhtml ใช้อยู่แล้ว (label.contracts.confirm_delete_doc) */
                    function ctMdDeleteDoc(no) {
                        env.swal({
                            title: env.t("label.contracts.confirm_delete_doc"),
                            icon: 'warning',
                            buttons: [env.t("chat.cancel"), env.t("label.cmd.delete_tip")],
                            dangerMode: true
                        }).then(function (willDelete) {
                            if (willDelete && window.rc_deleteProspectDoc) { rc_deleteProspectDoc([{ name: 'docNo', value: no }]); }
                        });
                    }
                    /* ★ 27/08: ของเดิม <a href="#{doc.attachfile}" target="_blank"> เปิด URL ไฟล์ตรงจาก
                       file server (คนละ origin กับแอป) — โดน CORS/ไฟร์วอลล์บาง environment = เห็นหน้า 404 ดิบจาก
                       nginx ของ file server เอง ต้องผ่าน same-origin /docproxy เหมือนทุกจุดดาวน์โหลดเอกสารในระบบ
                       (contracts.xhtml ctDownloadDoc / lead_detail.xhtml ldDownloadDoc) — ใช้ data-url/data-name
                       แทนการยัด URL ลง onclick ตรง ๆ กัน EL string มี quote/อักขระพิเศษแล้วพัง JS */
                    function ctMdDownloadDoc(el) {
                        var url = el && el.getAttribute('data-url');
                        var name = (el && el.getAttribute('data-name')) || 'download';
                        if (!url) { return; }
                        var proxied = '/docproxy?url=' + encodeURIComponent(url);
                        env.fetch(proxied).then(function (r) {
                            if (!r.ok) { throw new Error(r.headers.get('X-DocProxy-Reason') || ('HTTP_' + r.status)); }
                            return r.blob();
                        }).then(function (b) {
                            var href = URL.createObjectURL(b);
                            var a = document.createElement('a');
                            a.href = href; a.download = name;
                            document.body.appendChild(a); a.click(); a.remove();
                            tmo(function () { URL.revokeObjectURL(href); }, 1000);
                        })['catch'](function (err) {
                            /* err.message = รหัสสาเหตุจาก DocProxy (BLOCKED_HOST / UPSTREAM_404 / NETWORK ...) — บล็อกนี้ไม่อยู่ใน CDATA ห้ามใส่ตัวอักษร ampersand หรือ less-than แบบดิบ */
                            var why = err ? err.message : '';
                            env.swal({ title: env.t("label.cmd.file_not_found_on_server"), text: why ? ('[' + why + ']') : '', icon: 'error' });
                        });
                    }


  /* the entry points of the inline handlers and of the window.* functions */
  window.ctMdPickFiles = ctMdPickFiles;
  window.ctMdOnFilePicked = ctMdOnFilePicked;
  window.ctMdDeleteDoc = ctMdDeleteDoc;
  window.ctMdDownloadDoc = ctMdDownloadDoc;
  window.ctMdSetBusy = ctMdSetBusy;
  window.ctMdShowProgress = ctMdShowProgress;
  window.ctMdClearProgress = ctMdClearProgress;
  var EXPORTED = ["ctMdPickFiles","ctMdOnFilePicked","ctMdDeleteDoc","ctMdDownloadDoc","ctMdSetBusy","ctMdShowProgress","ctMdClearProgress","_contractId"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
